html='''<!doctype html><meta charset="utf-8"><title>Anna zero-call join audit</title><style>body{font:15px system-ui;background:#f5f2e8;color:#25332a;margin:24px;max-width:1100px}canvas{border:1px solid #9ca896;image-rendering:pixelated}button{padding:8px}.warn{color:#8a3b24}input{width:220px}</style><h1>Anna: existing-art join audit, zero calls</h1><p>Actual64world canvas/density1.5. Fixed logical support anchor can allow torso motion across different leg/body poses. No pixels/scales were fitted. Green line is worldY130. Small crosses are optional mathematical probes, not new art/support approval.</p><button id="play">Play both once</button> <label><input type="checkbox" id="overlay">show body/toe probes</label><br><canvas id="landing" width="360" height="180"></canvas><canvas id="takeoff" width="360" height="180"></canvas><p><label>Landing step<input id="landslider" type="range" min="0" max="23" value="0"></label><span id="landstate"></span></p><p><label>Takeoff step<input id="takeslider" type="range" min="0" max="26" value="0"></label><span id="takestate"></span></p><p class="warn">Landing: one-claw acquisition proposal then discrete wing-fold/compression. Takeoff: curled-claw toe-pin COUNTERFACTUAL, not a weighted supported phase. C reach/release are single held wing keys, each100ms; A has real wing drawings. Neither is complete/approved flight.</p><p>Playback stops at endpoints and only explicit Play resets it. This audits coordinate/contact interpretation; no Mac adapter, forces, bilateral anatomy or unseen footage claimed.</p><script>const data=DATA,inputs=INPUTS,probes=PROBES,urls=URLS;const imgs={};let ready=0,start=0,playing=false;function draw(name,t){const series=name==='landing'?data.landing:data.takeoffCounterfactual,s=series[t],f=inputs[s.renderFrameId],c=document.querySelector('#'+name),x=c.getContext('2d');x.imageSmoothingEnabled=false;x.fillStyle=name==='landing'?'#e4e6d6':'#24302e';x.fillRect(0,0,360,180);x.strokeStyle='#778a68';x.beginPath();x.moveTo(0,130);x.lineTo(360,130);x.stroke();let px=80+s.bodyOriginWorld[0]-f.declaredBodyOrigin[0]/1.5,py=s.bodyOriginWorld[1]-f.declaredBodyOrigin[1]/1.5;x.drawImage(imgs[f.renderFrameId],Math.round(px),Math.round(py),64,64);if(document.querySelector('#overlay').checked){x.fillStyle='#b94825';x.fillRect(Math.round(80+s.bodyOriginWorld[0])-1,Math.round(s.bodyOriginWorld[1])-1,3,3);for(const p of Object.values(probes))if(p.renderFrameId===f.renderFrameId){x.fillStyle='#238ec5';x.fillRect(Math.round(px+p.pixel[0]/1.5),Math.round(py+p.pixel[1]/1.5),1,1)}}document.querySelector(name==='landing'?'#landslider':'#takeslider').value=t;document.querySelector(name==='landing'?'#landstate':'#takestate').textContent=`tick${t} ${s.renderFrameId} / ${s.supportMode}`;window.joinAuditState=window.joinAuditState||{};window.joinAuditState[name]={tick:t,source:s.renderFrameId,root:s.bodyOriginWorld,supportMode:s.supportMode};}function redraw(){draw('landing',+document.querySelector('#landslider').value);draw('takeoff',+document.querySelector('#takeslider').value)}function loop(now){if(playing){const t=Math.max(0,Math.floor(Math.max(0,now-start)*30/1000));draw('landing',Math.min(23,t));draw('takeoff',Math.min(26,t));if(t>=26)playing=false}requestAnimationFrame(loop)}for(const[id,u]of Object.entries(urls)){imgs[id]=new Image;imgs[id].onload=()=>{if(++ready===Object.keys(urls).length){redraw();requestAnimationFrame(loop)}};imgs[id].src=u}document.querySelector('#play').onclick=()=>{start=performance.now();playing=true;draw('landing',0);draw('takeoff',0)};for(const id of ['landslider','takeslider'])document.querySelector('#'+id).oninput=()=>{playing=false;redraw()};document.querySelector('#overlay').onchange=redraw;</script>'''
